begin;
-- Phase 7 adds physical execution without changing commercial values.
create table public.project_execution_members(
 id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id),project_id uuid not null,user_id uuid not null,active boolean not null default true,version integer not null default 1,
 created_by uuid references public.profiles(id) default auth.uid(),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(organization_id,id),unique(project_id,user_id),
 foreign key(organization_id,project_id) references public.projects(organization_id,id),foreign key(organization_id,user_id) references public.organization_memberships(organization_id,user_id));
create function private.ops_project(org uuid,project uuid) returns boolean language sql stable security definer set search_path='' as $$
 select private.is_member(org) and exists(select 1 from public.projects p where p.organization_id=org and p.id=project and (private.has_permission(org,'execution.view_all') or p.assigned_user_id=auth.uid() or exists(select 1 from public.project_execution_members m where m.organization_id=org and m.project_id=p.id and m.user_id=auth.uid() and m.active)));
$$;
create function private.ops_access(org uuid,permission text,project uuid default null) returns boolean language sql stable security definer set search_path='' as $$
 select private.has_permission(org,permission) and private.entitled(org,'projects') and (project is null or private.ops_project(org,project)) and
 (permission not like 'inventory.%' and permission not like 'material_issue.%' or private.entitled(org,'purchasing')) and
 (permission not like 'work_order.%' and permission not like 'subcontractor.%' or private.entitled(org,'vendors'));
$$;
create function private.ops_require(org uuid,permission text,project uuid default null) returns void language plpgsql security definer set search_path='' as $$begin
 perform 1 from public.organizations where id=org for update;
 if not private.ops_access(org,permission,project) then raise exception 'Unavailable operation' using errcode='42501';end if;
end$$;
create function private.ops_immutable() returns trigger language plpgsql set search_path='' as $$begin raise exception 'Historical records are immutable; append a correction' using errcode='23514';end$$;
create table public.execution_plans(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id),project_id uuid not null,
 contract_id uuid not null,plan_number text not null,status text not null default 'not_started' check(status in ('not_started','planning','in_progress','on_hold','punch_list','ready_for_handover','handed_over','completed','cancelled')),manager_id uuid,notes text not null default '' check(length(notes)<=10000),planned_start date,planned_end date,actual_start date,actual_end date,check(planned_end>=planned_start),check(actual_end>=actual_start),check(isfinite(planned_start)),check(isfinite(planned_end)),check(isfinite(actual_start)),check(isfinite(actual_end)),unique(organization_id,plan_number),unique(contract_id),foreign key(organization_id,contract_id,project_id) references public.contracts(organization_id,id,project_id),foreign key(organization_id,manager_id) references public.organization_memberships(organization_id,user_id),version integer not null default 1 check(version>0),created_by uuid references public.profiles(id) default auth.uid(),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(organization_id,id),unique(organization_id,project_id,id),foreign key(organization_id,project_id) references public.projects(organization_id,id));
create table public.execution_plan_revisions(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id),project_id uuid not null,
 plan_id uuid not null,revision_number integer not null check(revision_number>0),estimate_revision_id uuid not null,status text not null default 'draft' check(status in ('draft','approved','superseded','cancelled')),scope_fingerprint text not null,snapshot jsonb,notes text not null default '' check(length(notes)<=10000),approved_by uuid references public.profiles(id),approved_at timestamptz,unique(plan_id,revision_number),foreign key(organization_id,project_id,plan_id) references public.execution_plans(organization_id,project_id,id),foreign key(organization_id,estimate_revision_id) references public.execution_estimate_revisions(organization_id,id),version integer not null default 1 check(version>0),created_by uuid references public.profiles(id) default auth.uid(),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(organization_id,id),unique(organization_id,project_id,id),foreign key(organization_id,project_id) references public.projects(organization_id,id));
create unique index execution_plan_one_draft on public.execution_plan_revisions(plan_id) where status='draft';create unique index execution_plan_one_approved on public.execution_plan_revisions(plan_id) where status='approved';
create table public.work_packages(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id),project_id uuid not null,
 plan_id uuid not null,area_id uuid,scope_id uuid,name text not null check(length(trim(name)) between 1 and 200),source_type text not null default 'manual' check(source_type in ('manual','quotation','change_order')),source_id uuid,scope_state text not null default 'in_execution' check(scope_state in ('not_estimated','estimated','procurement_required','procurement_ready','in_execution','completed','removed_pending_confirmation','no_longer_required')),weight text not null default '1' check(private.execution_decimal(weight)>0),notes text not null default '' check(length(notes)<=10000),foreign key(organization_id,project_id,plan_id) references public.execution_plans(organization_id,project_id,id),foreign key(organization_id,area_id) references public.project_areas(organization_id,id),foreign key(organization_id,scope_id) references public.execution_estimate_scope_items(organization_id,id),version integer not null default 1 check(version>0),created_by uuid references public.profiles(id) default auth.uid(),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(organization_id,id),unique(organization_id,project_id,id),foreign key(organization_id,project_id) references public.projects(organization_id,id));
create table public.project_milestones(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id),project_id uuid not null,
 plan_id uuid not null,name text not null check(length(trim(name)) between 1 and 200),description text not null default '',sequence integer not null default 0,owner_id uuid,status text not null default 'not_started' check(status in ('not_started','in_progress','blocked','completed','cancelled')),completion_percentage text not null default '0' check(private.execution_decimal(completion_percentage)<=100),planned_start date,planned_end date,actual_start date,actual_end date,check(planned_end>=planned_start),check(actual_end>=actual_start),check(isfinite(planned_start)),check(isfinite(planned_end)),check(isfinite(actual_start)),check(isfinite(actual_end)),notes text not null default '' check(length(notes)<=10000),foreign key(organization_id,project_id,plan_id) references public.execution_plans(organization_id,project_id,id),foreign key(organization_id,owner_id) references public.organization_memberships(organization_id,user_id),version integer not null default 1 check(version>0),created_by uuid references public.profiles(id) default auth.uid(),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(organization_id,id),unique(organization_id,project_id,id),foreign key(organization_id,project_id) references public.projects(organization_id,id));
create table public.project_tasks(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id),project_id uuid not null,
 plan_id uuid not null,area_id uuid,work_package_id uuid,milestone_id uuid,title text not null check(length(trim(title)) between 1 and 200),description text not null default '',assigned_to uuid,priority text not null default 'normal' check(priority in ('low','normal','high','urgent')),status text not null default 'todo' check(status in ('todo','in_progress','blocked','done','cancelled')),completion_percentage text not null default '0' check(private.execution_decimal(completion_percentage)<=100),weight text not null default '1' check(private.execution_decimal(weight)>0),block_reason text not null default '',blocked_at timestamptz,blocked_by uuid references public.profiles(id),planned_start date,planned_end date,actual_start date,actual_end date,check(planned_end>=planned_start),check(actual_end>=actual_start),check(isfinite(planned_start)),check(isfinite(planned_end)),check(isfinite(actual_start)),check(isfinite(actual_end)),notes text not null default '' check(length(notes)<=10000),foreign key(organization_id,project_id,plan_id) references public.execution_plans(organization_id,project_id,id),foreign key(organization_id,area_id) references public.project_areas(organization_id,id),foreign key(organization_id,project_id,work_package_id) references public.work_packages(organization_id,project_id,id),foreign key(organization_id,project_id,milestone_id) references public.project_milestones(organization_id,project_id,id),foreign key(organization_id,assigned_to) references public.organization_memberships(organization_id,user_id),check((status='done')=(completion_percentage::numeric=100)),check(status<>'blocked' or length(trim(block_reason))>=3),version integer not null default 1 check(version>0),created_by uuid references public.profiles(id) default auth.uid(),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(organization_id,id),unique(organization_id,project_id,id),foreign key(organization_id,project_id) references public.projects(organization_id,id));
create table public.task_dependencies(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id),project_id uuid not null,
 task_id uuid not null,predecessor_id uuid not null,unique(task_id,predecessor_id),check(task_id<>predecessor_id),foreign key(organization_id,project_id,task_id) references public.project_tasks(organization_id,project_id,id),foreign key(organization_id,project_id,predecessor_id) references public.project_tasks(organization_id,project_id,id),version integer not null default 1 check(version>0),created_by uuid references public.profiles(id) default auth.uid(),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(organization_id,id),unique(organization_id,project_id,id),foreign key(organization_id,project_id) references public.projects(organization_id,id));
create table public.inventory_locations(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id),
 name text not null check(length(trim(name)) between 1 and 200),kind text not null check(kind in ('central_store','warehouse','workshop','project_site','other')),site_project_id uuid,active boolean not null default true,notes text not null default '' check(length(notes)<=10000),foreign key(organization_id,site_project_id) references public.projects(organization_id,id),check((kind='project_site')=(site_project_id is not null)),version integer not null default 1 check(version>0),created_by uuid references public.profiles(id) default auth.uid(),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(organization_id,id));
create table public.inventory_lots(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id),
 receipt_item_id uuid not null,variant_id uuid not null,unit text not null,received_quantity text not null check(private.execution_decimal(received_quantity)>0),label text not null,unique(receipt_item_id),foreign key(organization_id,receipt_item_id) references public.goods_receipt_items(organization_id,id),foreign key(organization_id,variant_id) references public.material_variants(organization_id,id),version integer not null default 1 check(version>0),created_by uuid references public.profiles(id) default auth.uid(),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(organization_id,id));
create table public.inventory_lot_costs(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id),
 lot_id uuid not null unique,currency text not null check(currency ~ '^[A-Z]{3}$'),total_cost text not null check(private.execution_decimal(total_cost)>=0),precision integer not null check(precision between 0 and 6),foreign key(organization_id,lot_id) references public.inventory_lots(organization_id,id),version integer not null default 1 check(version>0),created_by uuid references public.profiles(id) default auth.uid(),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(organization_id,id));
create table public.material_issue_requests(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id),project_id uuid not null,
 request_number text not null,source_location_id uuid not null,destination_location_id uuid not null,requested_by uuid not null default auth.uid(),status text not null default 'draft' check(status in ('draft','submitted','approved','partially_issued','fully_issued','rejected','cancelled')),reason text not null check(length(trim(reason)) between 3 and 3000),approved_by uuid references public.profiles(id),approved_at timestamptz,unique(organization_id,request_number),foreign key(organization_id,source_location_id) references public.inventory_locations(organization_id,id),foreign key(organization_id,destination_location_id) references public.inventory_locations(organization_id,id),foreign key(organization_id,requested_by) references public.organization_memberships(organization_id,user_id),version integer not null default 1 check(version>0),created_by uuid references public.profiles(id) default auth.uid(),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(organization_id,id),unique(organization_id,project_id,id),foreign key(organization_id,project_id) references public.projects(organization_id,id));
create table public.material_issue_request_items(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id),project_id uuid not null,
 request_id uuid not null,variant_id uuid not null,unit text not null,quantity text not null check(private.execution_decimal(quantity)>0),approved_quantity text check(private.execution_decimal(approved_quantity)>=0 and approved_quantity::numeric<=quantity::numeric),unique(request_id,variant_id,unit),foreign key(organization_id,project_id,request_id) references public.material_issue_requests(organization_id,project_id,id),foreign key(organization_id,variant_id) references public.material_variants(organization_id,id),version integer not null default 1 check(version>0),created_by uuid references public.profiles(id) default auth.uid(),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(organization_id,id),unique(organization_id,project_id,id),foreign key(organization_id,project_id) references public.projects(organization_id,id));
create table public.inventory_transactions(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id),
 project_id uuid,number text not null,kind text not null check(kind in ('purchase_receipt','transfer','issue_to_site','return_from_site','consumption','scrap','damage','adjustment','count','reversal')),source_location_id uuid,destination_location_id uuid,request_item_id uuid,original_transaction_id uuid,area_id uuid,task_id uuid,work_package_id uuid,estimate_line_id uuid,movement_date date not null default current_date check(isfinite(movement_date)),reason text not null check(length(trim(reason)) between 3 and 3000),received_by text not null default '',idempotency_key uuid not null,request_hash text not null,document_snapshot jsonb not null,unique(organization_id,idempotency_key),unique(organization_id,number),foreign key(organization_id,project_id) references public.projects(organization_id,id),foreign key(organization_id,source_location_id) references public.inventory_locations(organization_id,id),foreign key(organization_id,destination_location_id) references public.inventory_locations(organization_id,id),foreign key(organization_id,request_item_id) references public.material_issue_request_items(organization_id,id),foreign key(organization_id,original_transaction_id) references public.inventory_transactions(organization_id,id),foreign key(organization_id,area_id) references public.project_areas(organization_id,id),foreign key(organization_id,task_id) references public.project_tasks(organization_id,id),foreign key(organization_id,work_package_id) references public.work_packages(organization_id,id),foreign key(organization_id,estimate_line_id) references public.execution_estimate_lines(organization_id,id),version integer not null default 1 check(version>0),created_by uuid references public.profiles(id) default auth.uid(),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(organization_id,id));
create unique index inventory_single_reversal on public.inventory_transactions(original_transaction_id) where kind='reversal';
create table public.inventory_movements(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id),
 project_id uuid,transaction_id uuid not null,lot_id uuid not null,location_id uuid not null,quantity text not null check(private.finance_decimal(quantity,true)<>0),foreign key(organization_id,project_id) references public.projects(organization_id,id),foreign key(organization_id,transaction_id) references public.inventory_transactions(organization_id,id),foreign key(organization_id,lot_id) references public.inventory_lots(organization_id,id),foreign key(organization_id,location_id) references public.inventory_locations(organization_id,id),unique(transaction_id,lot_id,location_id),version integer not null default 1 check(version>0),created_by uuid references public.profiles(id) default auth.uid(),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(organization_id,id));
create table public.inventory_counts(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id),
 location_id uuid not null,lot_id uuid not null,system_quantity text not null,physical_quantity text not null check(private.execution_decimal(physical_quantity)>=0),transaction_id uuid,reason text not null,foreign key(organization_id,location_id) references public.inventory_locations(organization_id,id),foreign key(organization_id,lot_id) references public.inventory_lots(organization_id,id),foreign key(organization_id,transaction_id) references public.inventory_transactions(organization_id,id),version integer not null default 1 check(version>0),created_by uuid references public.profiles(id) default auth.uid(),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(organization_id,id));
