 vendor_id uuid not null unique,specialization text not null default '',service_areas text not null default '',active boolean not null default true,notes text not null default '' check(length(notes)<=10000),foreign key(organization_id,vendor_id) references public.vendors(organization_id,id),version integer not null default 1 check(version>0),created_by uuid references public.profiles(id) default auth.uid(),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(organization_id,id));
create table public.subcontractor_work_orders(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id),project_id uuid not null,
 plan_id uuid not null,vendor_id uuid not null,area_id uuid,number text not null,title text not null,scope text not null check(length(trim(scope)) between 3 and 10000),unit text not null,quantity text not null check(private.execution_decimal(quantity)>0),status text not null default 'draft' check(status in ('draft','issued','in_progress','partially_completed','completed','cancelled')),completed_percentage text not null default '0' check(private.execution_decimal(completed_percentage)<=100),accepted_percentage text not null default '0' check(private.execution_decimal(accepted_percentage)<=completed_percentage::numeric),planned_start date,planned_end date,actual_start date,actual_end date,check(planned_end>=planned_start),check(actual_end>=actual_start),check(isfinite(planned_start)),check(isfinite(planned_end)),check(isfinite(actual_start)),check(isfinite(actual_end)),notes text not null default '' check(length(notes)<=10000),document_snapshot jsonb,unique(organization_id,number),foreign key(organization_id,project_id,plan_id) references public.execution_plans(organization_id,project_id,id),foreign key(organization_id,vendor_id) references public.vendors(organization_id,id),foreign key(organization_id,area_id) references public.project_areas(organization_id,id),version integer not null default 1 check(version>0),created_by uuid references public.profiles(id) default auth.uid(),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(organization_id,id),unique(organization_id,project_id,id),foreign key(organization_id,project_id) references public.projects(organization_id,id));
