 work_order_id uuid not null unique,currency text not null,agreed_amount text not null check(private.execution_decimal(agreed_amount)>=0),unit_rate text not null check(private.execution_decimal(unit_rate)>=0),foreign key(organization_id,project_id,work_order_id) references public.subcontractor_work_orders(organization_id,project_id,id),version integer not null default 1 check(version>0),created_by uuid references public.profiles(id) default auth.uid(),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(organization_id,id),unique(organization_id,project_id,id),foreign key(organization_id,project_id) references public.projects(organization_id,id));
