 work_order_id uuid not null,area_id uuid,quantity text not null check(private.execution_decimal(quantity)>0),unit text not null,measurement_date date not null check(isfinite(measurement_date)),note text not null check(length(trim(note)) between 3 and 3000),status text not null default 'measured' check(status in ('measured','verified','rejected','certified')),decision_reason text not null default '',certified_by uuid references public.profiles(id),certified_at timestamptz,foreign key(organization_id,project_id,work_order_id) references public.subcontractor_work_orders(organization_id,project_id,id),foreign key(organization_id,area_id) references public.project_areas(organization_id,id),version integer not null default 1 check(version>0),created_by uuid references public.profiles(id) default auth.uid(),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(organization_id,id),unique(organization_id,project_id,id),foreign key(organization_id,project_id) references public.projects(organization_id,id));
