 measurement_id uuid not null unique,currency text not null,unit_rate text not null,amount text not null check(private.execution_decimal(amount)>=0),foreign key(organization_id,project_id,measurement_id) references public.work_measurements(organization_id,project_id,id),version integer not null default 1 check(version>0),created_by uuid references public.profiles(id) default auth.uid(),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(organization_id,id),unique(organization_id,project_id,id),foreign key(organization_id,project_id) references public.projects(organization_id,id));
create table public.inspection_templates(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id),
 name text not null check(length(trim(name)) between 1 and 200),kind text not null default 'quality',is_final boolean not null default false,mandatory boolean not null default true,active boolean not null default true,checklist jsonb not null check(jsonb_typeof(checklist)='array' and jsonb_array_length(checklist) between 1 and 100),version integer not null default 1 check(version>0),created_by uuid references public.profiles(id) default auth.uid(),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(organization_id,id));
create table public.project_inspections(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id),project_id uuid not null,
 template_id uuid not null,area_id uuid,work_package_id uuid,predecessor_id uuid,number text not null,inspector_id uuid not null,status text not null default 'draft' check(status in ('draft','in_progress','passed','failed','requires_rework')),inspection_date date not null default current_date check(isfinite(inspection_date)),is_final boolean not null,mandatory boolean not null,template_snapshot jsonb not null,checklist jsonb not null,notes text not null default '' check(length(notes)<=10000),approved_at timestamptz,approved_by uuid references public.profiles(id),document_snapshot jsonb,unique(organization_id,number),foreign key(organization_id,template_id) references public.inspection_templates(organization_id,id),foreign key(organization_id,area_id) references public.project_areas(organization_id,id),foreign key(organization_id,project_id,work_package_id) references public.work_packages(organization_id,project_id,id),foreign key(organization_id,project_id,predecessor_id) references public.project_inspections(organization_id,project_id,id),foreign key(organization_id,inspector_id) references public.organization_memberships(organization_id,user_id),version integer not null default 1 check(version>0),created_by uuid references public.profiles(id) default auth.uid(),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(organization_id,id),unique(organization_id,project_id,id),foreign key(organization_id,project_id) references public.projects(organization_id,id));
create table public.project_snags(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id),project_id uuid not null,
